const courses={
 stack:{id:'stack',subject:'软件设计师',title:'栈与队列',version:'1.0',minutes:30,hwMinutes:8,priority:'P0',mastery:0,prereq:'建议先了解线性表；开课先用一个小问题诊断。',goal:'根据出入顺序追踪输出，并在新场景中选择栈或队列。',source:'study-prep-tracker / sd-mastery.md · B.数据结构；下面题目为交互示例自编题。',criteria:['能按后进先出与先进先出规则判断结构','能独立追踪一个未出现过的操作序列'],teaching:'栈在同一端加入和取出，最后加入的先取出（LIFO）。队列从一端加入、另一端取出，先加入的先取出（FIFO）。\n先确定操作规则，再按每一次加入/取出更新当前结构；不要只凭场景名字选答案。',example:'栈依次压入 1、2、3：弹出顺序是 3、2、1。队列依次加入 1、2、3：取出顺序是 1、2、3。',diagnosis:{type:'choice',prompt:'最近添加的一次撤销记录要最先被取出。这是什么结构？',options:['A. 队列','B. 栈','C. 不能判断'],expected:'B',reason:'最晚加入的最先取出，符合栈的后进先出。'},practice:{type:'exact',prompt:'向空栈依次压入 1、2、3，连续弹出三次。输出顺序是什么？',format:'只输入逗号分隔的数字，例如 1,2,3。',expected:'3,2,1',reason:'栈是后进先出，所以依次弹出 3、2、1。'},tests:[[{type:'choice',prompt:'一组任务要求先提交的先执行，且从两端分别加入和取出。选择什么结构？',options:['A. 栈','B. 队列','C. 无法判断'],expected:'B',reason:'提交顺序就是执行顺序，符合 FIFO。'},{type:'exact',prompt:'空栈：压入 4 → 压入 7 → 弹出一次 → 压入 9 → 弹出一次。两次输出是什么？',format:'用逗号分隔两次输出。',expected:'7,9',reason:'第一次弹出 7；加入 9 后，第二次弹出 9。'}],[{type:'choice',prompt:'先放入的物品可以留着，最近放入的必须最先取走。选择什么结构？',options:['A. 队列','B. 栈','C. 两者都可以'],expected:'B',reason:'取出最新加入的元素，符合 LIFO。'},{type:'exact',prompt:'空队列：加入 5 → 加入 8 → 取出一次 → 加入 6 → 取出一次。两次输出是什么？',format:'用逗号分隔两次输出。',expected:'5,8',reason:'队列第一次取出 5，剩下 8；加入 6 后先取出 8。'}]],homework:[{prompt:'① 空栈：压入 1、2 → 弹出 → 压入 3 → 弹出 → 弹出。写出三次输出。\n② 服务顺序必须和取号顺序相同，选择“栈”还是“队列”？',format:'两项用分号分隔，例如 1,2,3;栈。',answers:['2,3,1','队列']},{prompt:'① 空队列：加入 2、4 → 取出 → 加入 6 → 取出 → 取出。写出三次输出。\n② 总是首先移除最新一次记录，选择“栈”还是“队列”？',format:'两项用分号分隔。',answers:['2,4,6','栈']}],hwCriteria:['操作序列完整且顺序正确','结构选择与取出规则一致'],review:{type:'choice',prompt:'先加入 x，再加入 y。取出时先得到 x。根据这个规则，选择结构。',options:['A. 栈','B. 队列','C. 都是栈'],expected:'B',reason:'先入先出符合队列。'}},
 english:{id:'english',subject:'英语',title:'句子成分 · 技术短句',version:'1.0',minutes:20,hwMinutes:6,priority:'P0',mastery:2,prereq:'需要认识基础名词与动词，诊断会检查简单句主干。',goal:'在未出现过的技术句子中独立标出主语、谓语和宾语。',source:'study-prep-tracker / english-mastery.md；自编材料 english/readings/reading-001.md。',criteria:['能识别主语和承担动作的谓语','能定位动作作用的宾语，保持完整词组'],teaching:'先找表示动作的谓语，再问“谁做这个动作”，得到主语；最后问“动作作用于什么”，得到宾语。\n保留词组，不要只取其中的一个名词。例句 The engine shows errors.：主语 The engine，谓语 shows，宾语 errors。',example:'The developer writes code. → the developer | writes | code。程序员写代码，动作是 writes，不是名词 developer。',diagnosis:{type:'parts',prompt:'The game starts.\n标出主语和谓语。',format:'用 | 分隔，例如 the engine | runs。',expected:'the game|starts',reason:'The game 是主语，starts 是谓语，这句没有宾语。'},practice:{type:'parts',prompt:'The engine shows errors.\n标出完整的主语、谓语、宾语。',format:'主语 | 谓语 | 宾语',expected:'the engine|shows|errors',reason:'the engine 执行 shows 这个动作，errors 是宾语。'},tests:[[{type:'parts',prompt:'The tools help developers.\n独立标出主语、谓语和宾语。',format:'主语 | 谓语 | 宾语',expected:'the tools|help|developers',reason:'工具帮助开发者：the tools | help | developers。'},{type:'parts',prompt:'The team builds games.\n独立标出主语、谓语和宾语。',format:'主语 | 谓语 | 宾语',expected:'the team|builds|games',reason:'团队制作游戏：the team | builds | games。'}],[{type:'parts',prompt:'The program saves files.\n独立标出主语、谓语和宾语。',format:'主语 | 谓语 | 宾语',expected:'the program|saves|files',reason:'the program | saves | files。'},{type:'parts',prompt:'The artist creates models.\n独立标出主语、谓语和宾语。',format:'主语 | 谓语 | 宾语',expected:'the artist|creates|models',reason:'the artist | creates | models。'}]],homework:[{prompt:'拆解两个新句子：\n① The developer fixes bugs.\n② The engine loads textures.',format:'每句按 主语|谓语|宾语；两句用分号分隔。',answers:['the developer|fixes|bugs','the engine|loads|textures']},{prompt:'拆解两个新句子：\n① The tester finds errors.\n② The framework provides tools.',format:'每句按 主语|谓语|宾语；两句用分号分隔。',answers:['the tester|finds|errors','the framework|provides|tools']}],hwCriteria:['第一句完整主谓宾均正确','第二句完整主谓宾均正确'],review:{type:'parts',prompt:'The server sends messages.\n回忆句子分析方法，并标出主谓宾。',format:'主语 | 谓语 | 宾语',expected:'the server|sends|messages',reason:'the server | sends | messages。'}},
 vector:{id:'vector',subject:'游戏开发',title:'向量 · 点积与视野判断',version:'1.0',minutes:40,hwMinutes:18,priority:'P0',mastery:0,prereq:'基础坐标与向量运算；课程范围限定在二维/三维方向判断。',goal:'计算点积，并实现有零向量保护的视野角度判定。',source:'study-prep-tracker / gamedev-mastery.md · A.数学；项目为自编 UE 场景练习。',criteria:['能独立计算单位向量点积并解释方向','提交归一化、阈值与零向量处理的实现及边界结果'],teaching:'点积 a·b = axbx + ayby + azbz。两个非零向量归一化后，点积等于夹角余弦：同向 1、垂直 0、反向 -1。\n视野半角为 α 时：dot(normal(forward), normal(target-position)) >= cos(α)。要使用同一单位的角度，且先处理目标重合/零向量。',example:'单位 forward=(1,0)，目标方向=(0,1)：点积为 0，夹角 90°，不在 45° 半角视野内。',diagnosis:{type:'choice',prompt:'单位向量 (1,0) 和 (0,1) 的点积是多少？',options:['A. 1','B. 0','C. -1'],expected:'B',reason:'1×0 + 0×1 = 0。'},practice:{type:'exact',prompt:'计算 (1,0) 与 (-1,0) 的点积。',format:'只输入计算结果。',expected:'-1',reason:'1×(-1) + 0×0 = -1，两个方向相反。'},tests:[[{type:'exact',prompt:'计算单位向量 (0,1) 与 (1,0) 的点积。',format:'只输入数值。',expected:'0',reason:'0×1 + 1×0 = 0。'},{type:'exact',prompt:'计算单位向量 (0,1) 与 (0,-1) 的点积。',format:'只输入数值。',expected:'-1',reason:'0×0 + 1×(-1) = -1。'}],[{type:'exact',prompt:'计算单位向量 (1,0) 与 (1,0) 的点积。',format:'只输入数值。',expected:'1',reason:'1×1 = 1。'},{type:'exact',prompt:'计算单位向量 (-1,0) 与 (0,1) 的点积。',format:'只输入数值。',expected:'0',reason:'(-1)×0 + 0×1 = 0。'}]],homework:[{prompt:'提交一个半角 45° 的视野判断函数（代码或清晰伪代码）。\n附 0°、45°、90°、180° 和目标重合时的实际输出，以及对应输入。代码可以用 UE 的 FVector，也可用熟悉的语言。',format:'粘贴代码与实验结果，或读取文本文件到下方输入框。'}],hwCriteria:['两个方向均经过归一化，角度单位一致','阈值使用 cos(45°)，边界是否包含有明确说明','零向量/目标重合有明确处理，不发生除零','附可复现输入及 0°/45°/90°/180°/重合的实际结果'],review:{type:'exact',prompt:'两个单位方向垂直时点积是多少？请先独立回忆。',format:'只输入数值。',expected:'0',reason:'垂直方向夹角 90°，cos(90°)=0。'}}
};
const pages=[['today','⌂','今日'],['plan','▦','学习计划'],['courses','⌘','学习专栏'],['assignments','✎','作业'],['review','◷','验收与复习'],['stats','▤','学习复盘'],['notes','▧','笔记'],['settings','⚙','设置']];
function dateAt(n){const d=new Date(TODAY+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function shiftDate(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)}
function defaults(){return {page:'today',selected:null,active:null,sessions:{},threads:{workspace:[]},drafts:{},mastery:{stack:0,english:2,vector:0},plan:null,previousPlan:null,planDraft:null,version:0,availability:Array.from({length:7},(_,i)=>({date:dateAt(i),minutes:[0,6].includes(new Date(dateAt(i)+'T12:00:00').getDay())?60:45})),reviews:[],reviewRun:null,notes:[],pendingSummary:null,outline:null,goal:{main:'软件设计师',exam:'',english:'能独立理解简单技术句子，逐步阅读技术文档',game:'实现并解释一个可以复现的小实验'},settings:{reviewLimit:30,style:'先举例，再讲原理'},attachmentName:''}}
let state;try{state=Object.assign(defaults(),JSON.parse(null||'null')||{})}catch{state=defaults()}
state.availability=defaults().availability.map(a=>state.availability.find(old=>old.date===a.date)||a);
if(!pages.some(p=>p[0]===state.page)&&!['lesson','assignment','summary','review-run'].includes(state.page))state.page='today';
for(const s of Object.values(state.sessions)){if(s.runAt){s.elapsed+=Math.max(0,Math.floor((Date.now()-s.runAt)/1000));s.runAt=null}s.paused=true}
function esc(v){return String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
function save(){}
function toast(t){const e=document.getElementById('toast');e.textContent=t;e.classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.add('hidden'),3000)}
function btn(label,action,kind=''){return `<button class="btn ${kind}" data-action="${action}">${label}</button>`}
function badge(t,kind=''){return `<span class="tag ${kind}">${esc(t)}</span>`}
function head(title,sub,action=''){return `<div class="pagehead row"><div><h1>${title}</h1><p class="sub">${sub}</p></div>${action}</div>`}
function panel(title,body,sub=''){return `<section class="card"><h3>${title}</h3>${sub?`<p class="sub">${sub}</p>`:''}${body}</section>`}
function newSession(id){return {id,created:Date.now(),stage:'diagnosis',diagnosis:null,practicePass:false,practiceHint:false,attempt:0,index:0,answers:[],hinted:false,acceptance:{pass:false,done:false,source:'未验收'},homework:{versions:[],pass:false,hinted:false,variant:0,pending:false},elapsed:0,runAt:null,paused:true,messages:[],confirmed:false}}
function ses(id=state.selected){return state.sessions[id]}
function elapsed(s){return (s?.elapsed||0)+(s?.runAt?Math.max(0,Math.floor((Date.now()-s.runAt)/1000)):0)}
function clock(s){const n=elapsed(s);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function pauseActive(){const s=ses(state.active);if(s&&s.runAt){s.elapsed=elapsed(s);s.runAt=null;s.paused=true}}
function complete(s){return !!(s?.acceptance.pass&&s.homework.pass)}
function status(id){const s=ses(id);if(!s)return '未开始';if(complete(s))return s.confirmed?'已通过':'待确认记录';if(s.homework.pending)return '待人工核验';if(s.stage==='remedy')return '需补学';if(s.acceptance.pass)return '待作业';if(s.homework.pass)return '待验收';return '学习中'}
function thread(){if(['lesson','assignment','summary'].includes(state.page)&&ses())return ses().messages;return state.threads.workspace}
function draftKey(){return ['lesson','assignment','summary'].includes(state.page)&&state.selected?'course:'+state.selected:'workspace'}
function add(role,text){thread().push({role,text,at:Date.now()})}
function rememberDraft(){const e=document.getElementById('aiInput');if(e)state.drafts[draftKey()]=e.value}
function goto(page){rememberDraft();if(!['lesson','assignment'].includes(page))pauseActive();state.page=page;closeModal();save();render('top')}
function placeholder(){if(state.page==='assignment')return '在这里提交作业或修订内容，也可以输入“提示”…';if(state.page==='review-run')return '先独立回答当前复习题…';if(state.page==='lesson')return ['diagnosis','practice','acceptance'].includes(ses()?.stage)?'回答上方当前任务；Enter 提交，Shift+Enter 换行…':'围绕当前课程提问，或输入“举例”…';return '和 AI 沟通计划、课程或学习问题…'}
function render(where){const old=document.getElementById('workspace')?.scrollTop||0;const active=ses(state.active), c=active?courses[state.active]:null;const pageName=pages.find(p=>p[0]===state.page)?.[2]||({lesson:'课堂',assignment:'作业提交',summary:'确认学习记录','review-run':'独立复习'}[state.page]);
document.getElementById('app').innerHTML=`<div class="shell"><aside class="side"><div class="brand"><div class="orb">知</div>知序</div><nav class="navs">${pages.map(([id,icon,label])=>`<button class="nav ${state.page===id?'active':''}" data-action="goto('${id}')"><span>${icon}</span>${label}</button>`).join('')}</nav><select class="input mobile-nav" aria-label="页面导航" data-change="goto(this.value)">${pages.map(([id,ic,label])=>`<option value="${id}" ${state.page===id?'selected':''}>${label}</option>`).join('')}</select>${active?`<button class="session-link" data-action="startCourse('${c.id}')"><span class="tiny">${active.paused?'已暂停 · 继续课堂':'当前课堂'}</span><br><strong>${esc(c.title)}</strong><div class="tiny">${esc(stageName(active.stage))} · ${clock(active)}</div></button>`:''}<div class="sidefoot"><div class="tiny">三条学习线 · 一个沟通入口</div><div class="notice">学习数据保存在此电脑<br><span class="tiny">连接状态请查看设置</span></div></div></aside><main class="main"><header class="top"><div class="orb">✦</div><div class="topcopy"><strong>AI 学习教练</strong><div class="sub">${active?`${esc(c.title)} · ${active.paused?'已暂停':esc(stageName(active.stage))} · <span id="timer">${clock(active)}</span>`:`${pageName} · 把学习推进到下一步`}</div></div><div class="topcontrols">${active?btn(active.paused?'继续课堂':'暂停',active.paused?`startCourse('${c.id}')`:'pauseSession()','small')+btn('结束并整理',`endCourse('${c.id}')`,'small'):badge('桌面版','gray')}</div></header><div class="viewport" id="workspace" tabindex="0" aria-label="学习内容与对话区">${content()}${['lesson','assignment','review-run'].includes(state.page)?'':messages()}</div><footer class="compose"><textarea id="aiInput" aria-label="AI 对话和任务提交" placeholder="${placeholder()}" data-input="draftInput(this)" data-keydown="if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendAI()}">${esc(state.drafts[draftKey()]||'')}</textarea><div class="composefoot"><div class="tiny">${state.page==='assignment'?'<button class="attachments" data-action="document.getElementById(\'attachment\').click()">＋ 文本附件</button> '+esc(state.attachmentName||''):state.page==='lesson'?'当前输入用于本课程 · '+(ses()?.stage==='acceptance'?'独立验收':'学习对话'):'Enter 发送 · Shift+Enter 换行'}</div>${btn(['lesson','assignment','review-run'].includes(state.page)?'提交 ↑':'发送 ↑','sendAI()','primary small')}</div></footer></main></div>`;
const v=document.getElementById('workspace');v.scrollTop=where==='bottom'?v.scrollHeight:where==='top'?0:old;growInput(document.getElementById('aiInput'))}
function messages(){const list=thread();return list.length?`<div class="transcript" aria-label="本上下文对话记录">${list.map(m=>`<div class="message ${m.role==='user'?'user':'ai'}"><span class="label">${m.role==='user'?'你':'AI · 规则演示'}</span>${esc(m.text)}</div>`).join('')}</div>`:''}
function content(){return ({today:todayPage,plan:planPage,courses:coursesPage,lesson:lessonPage,assignments:assignmentsPage,assignment:assignmentPage,review:reviewPage,'review-run':reviewRunPage,summary:summaryPage,stats:statsPage,notes:notesPage,settings:settingsPage}[state.page]||todayPage)()}
function stageName(stage){return {diagnosis:'诊断',learn:'讲解',practice:'练习',ready:'待独立验收',acceptance:'独立验收',result:'验收通过',remedy:'补学'}[stage]||stage}
function todayPage(){const active=ses(state.active),next=Object.values(courses).find(c=>status(c.id)!=='已通过')||courses.stack;const dayTasks=state.plan?.tasks.filter(t=>t.date===TODAY)||[];const pending=Object.values(state.sessions).filter(s=>!s.homework.pass).length;return `<div class="section">${head('今天，从一个可完成的任务开始',new Date(TODAY+'T12:00:00').toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})+' · 时间安排可以随工作变化调整',btn('调整目标','goalModal()'))}<section class="hero"><div class="tiny">${active?'接着上次继续':'推荐下一步'}</div><h2 class="space">${active?esc(courses[state.active].title):esc(next.title)}</h2><p class="sub space">${active?`当前在${esc(stageName(active.stage))}，草稿与已提交内容保留。`:esc(next.goal)}</p><div class="actions space">${btn(active?'继续学习':'查看课程',active?`startCourse('${state.active}')`:`viewCourse('${next.id}')`,'primary')}${!state.plan?btn('先安排可用时间',"goto('plan')") :''}</div></section><div class="grid3">${panel('已确认通过',`<div class="kpi">${Object.keys(courses).filter(id=>status(id)==='已通过').length} / ${Object.keys(courses).length}</div><span class="tiny">课程验收 + 作业 + 记录确认</span>`)}${panel('待完成作业',`<div class="kpi">${pending}</div>${btn('查看作业',"goto('assignments')",'small')}`)}${panel('待复习',`<div class="kpi">${state.reviews.filter(r=>r.date<=TODAY).length}</div><span class="tiny">由确认过的学习证据生成</span>`)}</div>${panel('今天的安排',dayTasks.length?dayTasks.map(t=>`<div class="item"><div class="grow"><strong>${esc(t.title)}</strong><div class="sub">${t.minutes} 分钟 · ${esc(t.type)} · ${status(t.course)}</div></div>${btn('进入',t.type==='复习'?`startReview('${t.course}')`:t.type==='补交作业'?`openAssignment('${t.course}')`:`startCourse('${t.course}')`,'small')}</div>`).join(''):`<p class="sub">${state.plan?'今天没有排入任务。可以继续已有课程，或调整容量。':'还没有确认学习计划。可先做一门课的诊断，再根据可用时间安排。'}</p>${btn('查看计划',"goto('plan')",'small space')}`)}${panel('三条学习线',`<div class="list"><div>软件设计师：通过考试 ${state.goal.exam?'· 目标日期 '+esc(state.goal.exam):'· 考试日期待定'}</div><div>英语：${esc(state.goal.english)}</div><div>游戏开发：${esc(state.goal.game)}</div></div>`)}</div>`}
function goalModal(){openModal('学习目标',`<div class="field"><label>主要学习线</label><select id="goal-main" class="input">${['软件设计师','英语','游戏开发'].map(v=>`<option ${state.goal.main===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>软件设计师考试日期（可以留空）</label><input id="goal-exam" type="date" class="input" value="${esc(state.goal.exam)}"></div><div class="field"><label>英语要达到的能力</label><input id="goal-en" class="input" value="${esc(state.goal.english)}"></div><div class="field"><label>游戏开发要完成的能力产出</label><input id="goal-game" class="input" value="${esc(state.goal.game)}"></div><div class="actions space">${btn('保存目标','saveGoal()','primary')}${btn('取消','closeModal()')}</div>`)}
function saveGoal(){state.goal={main:document.getElementById('goal-main').value,exam:document.getElementById('goal-exam').value,english:document.getElementById('goal-en').value.trim(),game:document.getElementById('goal-game').value.trim()};closeModal();save();render();toast('目标已保存在本地')}
function taskPool(){const pool=state.reviews.filter(r=>r.date<=TODAY).map(r=>({id:'review-'+r.course,course:r.course,title:courses[r.course].title+' · 复习',type:'复习',minutes:8}));const ordered=Object.values(courses).sort((a,b)=>(a.subject===state.goal.main?-1:0)-(b.subject===state.goal.main?-1:0));for(const c of ordered){const s=ses(c.id);if(s?.confirmed&&complete(s))continue;const hw=s?.acceptance.pass&&!s.homework.pass;pool.push({id:'course-'+c.id,course:c.id,title:c.title,type:hw?'补交作业':'课程（含练习、验收与作业）',minutes:hw?c.hwMinutes:c.minutes})}return pool}
function buildPlan(slots){const used={},reviewUsed={},tasks=[],deferred=[];for(const t of taskPool()){let slot=slots.find(a=>(used[a.date]||0)+t.minutes<=Math.floor(a.minutes*.85)&&(t.type!=='复习'||(reviewUsed[a.date]||0)+t.minutes<=state.settings.reviewLimit));if(slot){used[slot.date]=(used[slot.date]||0)+t.minutes;if(t.type==='复习')reviewUsed[slot.date]=(reviewUsed[slot.date]||0)+t.minutes;tasks.push({...t,date:slot.date})}else deferred.push({...t,reason:t.type==='复习'&&t.minutes>state.settings.reviewLimit?'超过每日复习预算；需拆分复习或调整预算。':'没有足够长的时间窗口；可增加容量、拆分课程或延到下一轮。'})}return {slots:structuredClone(slots),tasks,deferred,created:Date.now()}}
function planPage(){const p=state.planDraft||state.plan;const available=state.availability.reduce((n,a)=>n+a.minutes,0);const usable=state.availability.reduce((n,a)=>n+Math.floor(a.minutes*.85),0);return `<div class="section">${head('学习计划','把复习、作业和学习都计入预算，留出 15% 缓冲。',btn('修改目标','goalModal()'))}<div class="grid2">${panel('未来七天的可用时间',`<p class="sub">初始数字是示例，请按实际工作安排修改。0 分钟代表当天不安排。</p><div class="tablewrap"><table class="table"><thead><tr><th>日期</th><th>可用分钟</th><th>可安排</th></tr></thead><tbody>${state.availability.map((a,i)=>`<tr><td>${a.date.slice(5)}</td><td><input class="input" style="width:85px" type="number" min="0" max="240" value="${a.minutes}" aria-label="${a.date} 可用分钟" data-change="changeCapacity(${i},this.value)"></td><td>${Math.floor(a.minutes*.85)} 分</td></tr>`).join('')}</tbody></table></div>`)}${panel('这轮学习的边界',`<div class="kpi">${available} <span class="sub">分钟可用</span></div><p>最多安排 ${usable} 分钟，预留 ${available-usable} 分钟。</p><p class="sub">主要学习线：${esc(state.goal.main)}。本轮任务范围是三个完整示例课程和已确认的复习。未设计课程不自动加入。</p><div class="actions space">${btn('生成计划草案','previewPlan()','primary')}${state.previousPlan?btn('撤销上次应用','undoPlan()'):''}</div><p class="sub">想临时调整，可以在底部说“今天只有 15 分钟”。会先生成草案。</p>`)}</div>${p?planPreview(p):'<div class="empty">填写时间后生成草案。当前尚未应用任何安排。</div>'}</div>`}
function changeCapacity(i,v){state.availability[i].minutes=Math.min(240,Math.max(0,parseInt(v)||0));state.planDraft=null;save();render()}
function previewPlan(){state.planDraft=buildPlan(state.availability);save();render();document.getElementById('plan-preview')?.scrollIntoView({block:'start'});toast('草案已生成，确认应用后生效')}
function planPreview(p){const total=p.tasks.reduce((n,t)=>n+t.minutes,0);const before=state.plan?.tasks.reduce((n,t)=>n+t.minutes,0)||0;return `<section class="card" id="plan-preview"><div class="row"><div><h2>${state.planDraft?'待确认草案':'已应用计划 · v'+state.version}</h2><p class="sub">${state.planDraft?`已排工作量：${before} → ${total} 分钟；草案容量 ${p.slots.reduce((n,a)=>n+a.minutes,0)} 分钟`:`已安排 ${total} 分钟`}</p></div>${state.planDraft?`<div class="actions">${btn('应用草案','applyPlan()','primary')}${btn('取消草案','cancelPlan()')}</div>`:''}</div><div class="tablewrap space"><table class="table"><thead><tr><th>任务</th><th>原安排 → 草案</th><th>分钟</th><th>类型</th></tr></thead><tbody>${p.tasks.map(t=>`<tr><td>${esc(t.title)}</td><td>${state.plan?.tasks.find(x=>x.id===t.id)?.date||'未安排'} ${state.planDraft?'→ '+t.date:''}</td><td>${t.minutes}</td><td>${esc(t.type)}</td></tr>`).join('')}</tbody></table></div>${p.deferred.length?`<div class="notice amber space">未排入：${p.deferred.map(t=>esc(t.title)+'（'+t.minutes+' 分钟）').join('、')}。${esc(p.deferred[0].reason)}</div>`:''}<details class="space"><summary>每天容量核对</summary>${p.slots.map(a=>{let n=p.tasks.filter(t=>t.date===a.date).reduce((v,t)=>v+t.minutes,0);return `<div class="item"><span>${a.date}</span><span>${n} / ${Math.floor(a.minutes*.85)} 分钟可排，原容量 ${a.minutes} 分钟</span></div>`}).join('')}</details></section>`}
function applyPlan(){if(!state.planDraft)return;if(state.planDraft.slots.some(a=>a.date<TODAY))return toast('这份草案包含过去日期，请重新生成未来七天安排');state.previousPlan={plan:structuredClone(state.plan),availability:structuredClone(state.availability)};state.plan=structuredClone(state.planDraft);state.availability=structuredClone(state.planDraft.slots);state.planDraft=null;state.version++;save();render();toast('计划已在本地应用')}
function cancelPlan(){state.planDraft=null;save();render()}
function undoPlan(){if(!state.previousPlan)return;state.plan=state.previousPlan.plan;state.availability=state.previousPlan.availability;state.previousPlan=null;state.planDraft=null;state.version++;save();render();toast('已撤销上一次计划应用与容量变更')}
function viewCourse(id){rememberDraft();pauseActive();state.selected=id;state.page='courses';save();render('top')}
function coursesPage(){if(state.selected)return courseDetail(courses[state.selected]);return `<div class="section">${head('课程','先明确能做什么，再开始学习。')}<div class="grid3">${Object.values(courses).map(c=>`<article class="card">${badge(c.subject)} <span class="tiny">${c.priority}</span><h2 class="space">${c.title}</h2><p class="sub">${c.goal}</p><div class="actions space">${badge(status(c.id),status(c.id)==='已通过'?'green':'gray')}<span class="tiny">总计约 ${c.minutes} 分钟 · v${c.version}</span></div>${btn('查看课程',`viewCourse('${c.id}')`,'primary small space')}</article>`).join('')}</div><details><summary>现有学习目录 · ${legacy.length} 个知识点（只读导入）</summary><p class="sub space">旧记录保留原值。其余知识点需要设计目标、材料、作业和验收标准，才成为可开课的课程。</p><input class="input space" placeholder="搜索知识点或学习线" aria-label="搜索知识点" data-input="filterLegacy(this.value)"><div class="tablewrap"><table class="table"><thead><tr><th>学习线 / 模块</th><th>知识点</th><th>优先级</th><th>旧掌握度</th><th>课程设计</th></tr></thead><tbody>${legacy.map(t=>`<tr data-topic="${esc(t.subject+' '+t.module+' '+t.title)}"><td>${esc(t.subject)}<br><span class="tiny">${esc(t.module)}</span></td><td>${esc(t.title)}</td><td>${esc(t.priority)}</td><td>${t.mastery}/5<br><span class="tiny">${esc(t.updated==='-'?'尚无证据日期':t.updated)}</span></td><td>${btn('设计草案',`outlineModal('${esc(t.title)}','${esc(t.subject)}')`,'small')}</td></tr>`).join('')}</tbody></table></div></details>${state.outline?panel('待设计课程草案',`<strong>${esc(state.outline.title)}</strong><pre class="pre space">${esc(state.outline.body)}</pre><p class="sub">草案未启用；需要确认题目、参考答案与材料来源后才能执行验收。</p>`):''}</div>`}
function filterLegacy(v){document.querySelectorAll('[data-topic]').forEach(e=>e.hidden=!e.dataset.topic.toLowerCase().includes(v.toLowerCase()))}
function courseDetail(c){return `<div class="section">${head(c.title,c.subject+' · 课程版本 '+c.version,btn('返回课程目录','backCourses()'))}<section class="hero"><h2>学完能够做什么</h2><p class="space">${esc(c.goal)}</p><div class="actions space">${badge(status(c.id),'gray')}<span class="sub">总计约 ${c.minutes} 分钟，其中作业约 ${c.hwMinutes} 分钟</span>${btn(ses(c.id)?'继续课堂':'开始诊断',`startCourse('${c.id}')`,'primary')}</div></section><div class="grid2">${panel('先修与材料',`<p>${esc(c.prereq)}</p><p class="sub">材料来源：${esc(c.source)}</p>`)}${panel('怎样算通过',`<ol class="criteria">${c.criteria.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="sub">两项独立验收均正确且无提示，必交作业达标，最后确认学习记录。</p>`)}</div>${panel('课程安排',`<div class="steps">${['诊断','讲解','练习','独立验收','作业产出','确认记录'].map(t=>`<span class="step">${t}</span>`).join('')}</div><p class="sub">练习和作业允许来回修订；获取帮助不等于独立通过。项目运行结果需另行核验。</p>`)}${panel('必交作业',`<p style="white-space:pre-wrap">${esc(c.homework[0].prompt)}</p><ul class="criteria">${c.hwCriteria.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${btn('查看作业',`openAssignment('${c.id}')`,'small')}`)}</div>`}
function backCourses(){state.selected=null;goto('courses')}
function outlineModal(title,subject){openModal('设计课程草案 · '+esc(title),`<p class="sub">把知识点转成可观察能力，草案保存后仍需补充正式题库与材料。</p><div class="field"><label>学完能做什么</label><textarea id="outline-goal" class="input" placeholder="例如：在新的场景中独立完成一项任务，并解释关键步骤。"></textarea></div><div class="field"><label>提交什么，以及怎样判断达标</label><textarea id="outline-rubric" class="input" placeholder="产出、逐项标准、验收题来源、失败后的补学内容。"></textarea></div>${btn('保存为草案',`saveOutline('${esc(title)}','${esc(subject)}')`,'primary space')}`)}
function saveOutline(title,subject){const goal=document.getElementById('outline-goal').value.trim(),rubric=document.getElementById('outline-rubric').value.trim();if(!goal||!rubric)return toast('请填写目标和验收依据');state.outline={title,subject,body:'目标：'+goal+'\n产出与验收：'+rubric+'\n状态：待补充教学材料、题目与参考答案'};save();closeModal();render();toast('课程草案已保存，尚未启用')}
function startCourse(id){rememberDraft();if(state.active!==id)pauseActive();state.selected=id;state.active=id;state.page='lesson';const s=state.sessions[id]||(state.sessions[id]=newSession(id));if(!s.runAt){s.paused=false;s.runAt=Date.now()}save();render(s.messages.length?'bottom':'top')}
function pauseSession(){rememberDraft();pauseActive();save();render();toast('课堂已暂停，当前题目和草稿保留')}
function question(q,label){return `<section class="task">${badge(label)}<div class="question">${esc(q.prompt)}</div>${q.options?q.options.map(o=>`<div class="option">${esc(o)}</div>`).join(''):''}<p class="sub">${esc(q.format||'在底部输入 A、B 或 C，可附解释。')}</p></section>`}
function currentQ(c,s){if(s.stage==='diagnosis')return c.diagnosis;if(s.stage==='practice')return c.practice;if(s.stage==='acceptance')return c.tests[s.attempt]?.[s.index];return null}
function lessonPage(){const c=courses[state.selected],s=ses();if(!s)return courseDetail(c);const q=currentQ(c,s);let body='';if(q)body=question(q,s.stage==='acceptance'?`独立验收 ${s.index+1}/2 · 新题组 ${s.attempt+1}${s.hinted?' · 本轮已转为训练':''}`:stageName(s.stage));else if(s.stage==='learn')body=panel('从规则理解到操作',`<p style="white-space:pre-wrap">${esc(c.teaching)}</p><div class="notice space">${esc(c.example)}</div><div class="actions space">${btn('做一道练习',"setStage('practice')",'primary')}${btn('已有基础，直接验收',"startAcceptance()")}</div>`);else if(s.stage==='ready')body=panel('可以尝试独立验收',`<p>${s.practicePass?'练习已完成'+(s.practiceHint?'（使用过帮助）':''):'你选择了直接检查已有基础'}。接下来使用新的题目，按课程标准逐项检查。</p><div class="actions space">${btn('开始独立验收','startAcceptance()','primary')}${btn('先完成作业',`openAssignment('${c.id}')`)}</div>`);else if(s.stage==='result')body=panel('本轮独立验收通过',`<div class="notice green space">两项均正确，未获取提示。这次结果只支持当前课程目标范围。</div><p>必交作业：${s.homework.pass?'已达标':'待完成'}。${complete(s)?'可以检查并确认学习记录。':'补交作业后再确认课程通过。'}</p><div class="actions space">${btn(s.homework.pass?'整理并确认记录':'完成必交作业',s.homework.pass?`endCourse('${c.id}')`:`openAssignment('${c.id}')`,'primary')}</div>`);else if(s.stage==='remedy')body=panel('先补上这一处，再用新题检查',`<p>本轮${s.hinted?'使用了提示，只能算训练':'有未满足标准的回答'}。</p><div class="list">${s.answers.map((a,i)=>`<div class="feedback ${a.correct?'pass':'fail'}">第 ${i+1} 项：${a.correct?'正确':'未达标'} · ${esc(a.reason)}</div>`).join('')}</div><p style="white-space:pre-wrap">${esc(c.teaching)}</p><div class="actions space">${s.attempt<c.tests.length-1?btn('用新题重新验收','retryAcceptance()','primary'):'<span class="sub">当前新题库已用完，需要补充题目或人工复核，不能重复旧题自动升级。</span>'}${btn('返回讲解',"setStage('learn')")}</div>`);
return `<div class="section">${head(c.title,c.goal,btn('课程标准',`viewCourse('${c.id}')`))}<div class="steps">${['diagnosis','learn','practice','acceptance'].map(x=>`<span class="step ${s.stage===x?'on':''}">${stageName(x)}</span>`).join('')}</div>${s.paused?`<div class="notice amber">课堂已暂停。${btn('继续计时并学习',`startCourse('${c.id}')`,'small')}</div>`:''}${messages()}${body}<details><summary>本课评分与已提交证据</summary><ol class="criteria">${c.criteria.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="sub">独立验收：${s.acceptance.done?(s.acceptance.pass?'通过':'未通过 / 已转为训练'):'未完成'} · 作业：${s.homework.pass?'达标':s.homework.pending?'待用户核验':'待提交/修订'} · 当前正式掌握度 ${state.mastery[c.id]}/5</p></details></div>`}
function setStage(stage){rememberDraft();ses().stage=stage;save();render('bottom')}
function startAcceptance(){const s=ses(),c=courses[state.selected];if(s.acceptance.pass)return toast('本课程已有独立通过证据，可以完成作业并确认记录');const used=s.acceptance.done||s.answers.length>0||s.hinted;const next=s.attempt+(used?1:0);if(next>=c.tests.length)return toast('没有未使用的新题，需要补充题库或人工复核');s.attempt=next;s.stage='acceptance';s.index=0;s.answers=[];s.hinted=false;s.acceptance={done:false,pass:false,source:'内置答案核对'};save();render('bottom')}
function retryAcceptance(){startAcceptance()}
function norm(v){return String(v).toLowerCase().trim().replace(/[，]/g,',').replace(/[；]/g,';').replace(/[。.]$/,'').split('|').map(x=>x.trim().replace(/\s+/g,' ')).join('|')}
function grade(q,v){if(q.type==='choice'){const m=v.trim().match(/^([abc])(?:[\s.、:：]|$)/i);return !!m&&m[1].toUpperCase()===q.expected}if(q.type==='parts')return norm(v)===norm(q.expected);return norm(v).replace(/\s/g,'')===norm(q.expected).replace(/\s/g,'')}
function answerCourse(v){const s=ses(),c=courses[state.selected];if(/^(暂停|先到这里|先停一下)$/.test(v)){pauseActive();add('ai','已暂停，题目与草稿会保留。');return}if(/^(结束学习|结束|整理记录|总结)$/.test(v)){add('ai','已按本次提交整理记录草案，请检查后确认。');endCourse(c.id);return}if(/^(开始验收|独立验收)$/.test(v)){startAcceptance();return}if(/^(下一步|开始练习)$/.test(v)&&s.stage==='learn'){s.stage='practice';return}if(/提示|举例|解释|为什么|看答案|换种/.test(v)){if(s.stage==='acceptance')s.hinted=true;if(s.stage==='practice')s.practiceHint=true;add('ai',(s.stage==='acceptance'?'本轮获取了帮助，结果将作为训练，需要再用新题独立验收。\n':'')+c.teaching+'\n'+c.example);return}const q=currentQ(c,s);if(!q){add('ai',c.example+'\n可以按上方课程任务继续，也可以就这个概念提问。');return}const correct=grade(q,v);add('ai',(correct?'这一项符合标准。':'这一项还没达到标准。')+'\n'+q.reason);if(s.stage==='diagnosis'){s.diagnosis={answer:v,correct};s.stage='learn';add('ai',correct?'诊断说明你已有这部分基础，可以简读讲解后尝试新题。':'我们先补这条规则，再做一次带反馈的练习。')}else if(s.stage==='practice'){s.practicePass=correct;if(correct)s.stage='ready';else s.practiceHint=true}else{ s.answers.push({answer:v,correct,reason:q.reason});s.index++;if(s.index>=c.tests[s.attempt].length){s.acceptance={done:true,pass:s.answers.every(a=>a.correct)&&!s.hinted,source:s.hinted?'有帮助的训练':'客观内置答案核对',attempt:s.attempt};s.stage=s.acceptance.pass?'result':'remedy';add('ai',s.acceptance.pass?'本轮两项均正确且未使用帮助；现在检查必交作业。':'本轮尚未取得独立通过。上方已列出补学内容与新题重试入口。')}}s.confirmed=false}
function assignmentsPage(){return `<div class="section">${head('作业','作业就是课程的能力产出，可以课堂完成，也可以暂停后补交。')}<div class="grid3">${Object.values(courses).map(c=>{const h=ses(c.id)?.homework;return panel(c.title,`<p class="sub">${c.subject} · 约 ${c.hwMinutes} 分钟 · 本示例不强制截止时间</p><div class="actions space">${badge(h?.pass?'已达标':h?.pending?'待人工核验':h?.versions.length?'待修订':'待提交',h?.pass?'green':'gray')}<span class="tiny">${h?.versions.length||0} 个提交版本</span></div><ul class="criteria">${c.hwCriteria.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${btn(h?.pass?'查看证据':'进入作业',`openAssignment('${c.id}')`,'primary small')}`)}).join('')}</div></div>`}
function openAssignment(id){rememberDraft();pauseActive();state.selected=id;state.active=id;state.page='assignment';if(!ses(id))state.sessions[id]=newSession(id);save();render('top')}
function assignmentPage(){const c=courses[state.selected],h=ses()?.homework;if(!h)return assignmentsPage();const t=c.homework[Math.min(h.variant,c.homework.length-1)];const last=h.versions.at(-1);return `<div class="section">${head(c.title+' · 必交作业',`v${c.version} · 约 ${c.hwMinutes} 分钟 · 提交不会自动改变掌握度`,btn('返回课堂',`startCourse('${c.id}')`))}${question(t,'当前任务 · 提交到下方唯一输入框')}${panel('评分标准',`<ol class="criteria">${c.hwCriteria.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p class="sub">${c.id==='vector'?'可以运行 JavaScript 实验并提交实际日志；C++ / UE 工程请在本地运行，再留下核验说明。':'按逐项标准核对答案；开放题使用 AI 评审，可查看反馈并修订提交。'}</p>`)}${messages()}${last?panel('最新提交 · 第 '+h.versions.length+' 版',`<div class="actions space">${badge(h.pass?'已达标':h.pending?'待人工核验':'需修订',h.pass?'green':'amber')}<span class="tiny">${esc(last.source)}${last.hinted?' · 使用过帮助':''}</span></div><pre class="pre space">${esc(last.body)}</pre><div class="list">${last.rubric.map(x=>`<div class="feedback ${x.pass===null?'':x.pass?'pass':'fail'}">${x.pass===null?'待核验':x.pass?'✓':'○'} ${esc(x.label)}${x.reason?' · '+esc(x.reason):''}</div>`).join('')}</div>${h.pending?projectReview(c):''}${!h.pass&&!h.pending?`<div class="actions space">${h.variant<c.homework.length-1?btn('换一份新任务重做','newHomework()'):''}<span class="sub">在底部输入修订版本，每次提交都保留。</span></div>`:''}${h.pass?btn(ses().acceptance.pass?'整理并确认学习记录':'继续独立验收',ses().acceptance.pass?`endCourse('${c.id}')`:`startCourse('${c.id}')`,'primary space'):''}`):'<div class="empty">还没有提交记录。题目和标准已在上方，完成后在底部输入框提交。</div>'}${h.versions.length>1?`<details><summary>查看 ${h.versions.length-1} 个历史版本</summary>${h.versions.slice(0,-1).map((v,i)=>`<h3 class="space">第 ${i+1} 版</h3><pre class="pre">${esc(v.body)}</pre>`).join('')}</details>`:''}</div>`}
function submitHomework(v){const c=courses[state.selected],s=ses(),h=s.homework,t=c.homework[Math.min(h.variant,c.homework.length-1)];if(/^提示|^解释/.test(v)){h.hinted=true;add('ai','这次作业使用了帮助，需要用新的等价任务再证明独立完成。\n'+c.teaching);return}const project=c.id==='vector';const parts=v.split(/[;；\n]/).map(norm).filter(Boolean);const rubric=c.hwCriteria.map((label,i)=>({label,pass:project?null:parts[i]===norm(t.answers[i]),reason:project?'需要材料与实际结果支持':parts[i]===norm(t.answers[i])?'符合本项答案':'请对照对应题目重新检查，不仅需要自述已完成'}));const passed=!project&&rubric.every(r=>r.pass)&&!h.hinted;h.versions.push({body:v,at:Date.now(),hinted:h.hinted,rubric,source:project?'待用户核验 · 原型未执行代码':'客观内置答案核对'});h.pass=passed;h.pending=project;s.confirmed=false;state.attachmentName='';add('ai',project?'材料已作为新版本保留。请检查上方四项项目标准并填写核验说明；原型没有运行这段代码。':passed?'作业各项均达标，未使用帮助。还需满足独立验收并确认记录。':h.hinted?'这次提交保留为训练成果，不能取得独立达标；请换新任务再尝试。':'提交已保留。上方逐项列出了还需修订的内容。')}
function newHomework(){const h=ses().homework;h.variant++;h.hinted=false;h.pass=false;save();render('top')}
function projectReview(c){return `<div class="notice amber space">需要用户核验。请实际运行并检查提交结果，下面的确认记录为用户提供的证据。</div><div class="checkboxes">${c.hwCriteria.map((t,i)=>`<label><input id="rubric-${i}" type="checkbox">${esc(t)}</label>`).join('')}</div><div class="field"><label>核验说明：在哪运行、对应结果、边界处理（至少 10 个字）</label><textarea id="review-note" class="input" placeholder="记录实际检查过程和结果，不仅写“通过”。"></textarea></div>${btn('确认用户核验结果','confirmProject()','primary space')}`}
function confirmProject(){const c=courses[state.selected],h=ses().homework,last=h.versions.at(-1),note=document.getElementById('review-note').value.trim();if(h.hinted)return toast('本版本使用过帮助，不能凭核验勾选取得独立达标；需要新的等价项目任务。');if(!c.hwCriteria.every((_,i)=>document.getElementById('rubric-'+i).checked)||note.length<10||last.body.trim().length<40)return toast('请提供完整材料、逐项核验，并填写具体说明');last.rubric=last.rubric.map(x=>({...x,pass:true,reason:'用户核验：'+note}));last.source='用户核验（来自用户工程环境）';last.reviewNote=note;h.pass=true;h.pending=false;ses().confirmed=false;save();render();toast('已保留用户核验证据，未冒充代码执行结果')}
function endCourse(id){rememberDraft();pauseActive();state.selected=id;const s=ses(id),c=courses[id];if(!s)return;const facts=[`课程：${c.subject} / ${c.title}，版本 ${c.version}`,`实际专注：${clock(s)}`,`诊断：${s.diagnosis?(s.diagnosis.correct?'本题正确':'本题需巩固'):'未进行'}`,`练习：${s.practicePass?'本题完成'+(s.practiceHint?'（有帮助）':''):'未取得本题完成证据'}`,`独立验收：${s.acceptance.done?(s.acceptance.pass?'两项均通过，无提示':'未通过 / 仅训练'):'未完成'}`,`作业：${s.homework.versions.length} 个版本，${s.homework.pass?'达标':s.homework.pending?'待人工核验':'尚未达标'}`,`课程状态：${complete(s)?'完成条件已满足，等待确认':'仍有未完成标准'}`,`作业证据来源：${s.homework.versions.at(-1)?.source||'无'}`].join('\n');state.pendingSummary={course:id,text:facts,score:complete(s)?Math.max(state.mastery[id],3):state.mastery[id],confidence:3,date:dateAt(complete(s)?3:1)};state.page='summary';save();render('top')}
function summaryPage(){const p=state.pendingSummary;if(!p)return '<div class="empty">先结束一场学习，再检查它的记录。</div>';const s=ses(p.course);return `<div class="section">${head('检查学习记录','只依据本次提交生成。自信度不会直接覆盖正式掌握度。')}<section class="card"><div class="field"><label>总结草稿（可以编辑）</label><textarea id="summary-text" class="input" style="min-height:210px" data-input="state.pendingSummary.text=this.value;save()">${esc(p.text)}</textarea></div><div class="grid2"><div class="field"><label>正式掌握度提案</label><div class="notice">${state.mastery[p.course]}/5 → ${p.score}/5<br>${complete(s)?'依据：独立验收 + 达标作业。仅覆盖当前课程目标。':'完成证据不足，保留原掌握度，不靠自评升级。'}</div></div><div class="field"><label>你的自信程度（与掌握度分别记录）</label><select id="confidence" class="input" data-change="state.pendingSummary.confidence=Number(this.value);save()">${[1,2,3,4,5].map(n=>`<option value="${n}" ${p.confidence===n?'selected':''}>${n}/5</option>`).join('')}</select><label>下一次复习建议（可调整）</label><input id="next-review" type="date" min="${TODAY}" value="${p.date}" class="input" data-change="state.pendingSummary.date=this.value;save()"></div></div><p class="sub space">确认后保存到这台电脑，笔记状态为“尚未云同步”。可以导出 Markdown 检查。完成条件不足时仍可记录进展。</p><div class="actions space">${btn('确认记录与变更','confirmSummary()','primary')}${btn('继续原课程',`startCourse('${p.course}')`)}</div></section></div>`}
function confirmSummary(){const p=state.pendingSummary,s=ses(p?.course);if(!p||!s)return;if(!p.text.trim()||!p.date||p.date<TODAY)return toast('请检查总结与复习日期');const id='session-'+p.course+'-'+s.created;state.mastery[p.course]=complete(s)?p.score:state.mastery[p.course];const c=courses[p.course],body=p.text+`\n\n确认掌握度：${state.mastery[p.course]}/5\n自信度：${p.confidence}/5\n复习日期：${p.date}\n保存状态：这台电脑；尚未云同步`;const note={id,title:TODAY+' · '+c.title,text:body,at:Date.now(),course:p.course};const ni=state.notes.findIndex(n=>n.id===id);if(ni>=0)state.notes[ni]=note;else state.notes.push(note);if(!s.confirmed){const r=state.reviews.find(r=>r.course===p.course);if(r){r.date=p.date;r.needsHelp=!complete(s)}else state.reviews.push({course:p.course,date:p.date,needsHelp:!complete(s),history:[]})}s.confirmed=true;s.confidence=p.confidence;state.pendingSummary=null;state.page='notes';save();render('top');toast('记录与变更已确认，本地保存成功')}
function reviewPage(){const pending=Object.values(courses).filter(c=>ses(c.id)&&!ses(c.id).acceptance.pass);return `<div class="section">${head('验收与复习','验收检查新能力；复习检查一段时间后能否独立回忆。')}<div class="grid2">${panel('待验收与补学',pending.length?pending.map(c=>`<div class="item"><div class="grow"><strong>${esc(c.title)}</strong><div class="sub">${status(c.id)} · ${ses(c.id).acceptance.done?'上一轮未取得独立通过':'尚未完成独立验收'}</div></div>${btn('继续',`startCourse('${c.id}')`,'small')}</div>`).join(''):'<p class="sub">目前没有已开始但尚未通过的验收任务。</p>')}${panel('复习预算',`<p>每日最多 ${state.settings.reviewLimit} 分钟。先复习到期与需补学的条目。</p><p class="sub">建议日期可调整，延期保留记录。重复题不用于自动升级掌握度。</p>`)}</div>${panel('已确认的复习队列',state.reviews.length?state.reviews.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(r=>`<div class="item"><div class="grow"><strong>${esc(courses[r.course].title)}</strong><div class="sub">${r.date} · ${r.date<=TODAY?'今天可复习':'尚未到期，可提前检查'} · ${r.needsHelp?'先补学':'独立回忆'} · ${r.history.length} 次记录</div></div><div class="actions">${btn('开始复习',`startReview('${r.course}')`,'primary small')}${btn('延期一天',`deferReview('${r.course}')`,'small')}</div></div>`).join(''):'<p class="sub">确认一份学习记录后，这里会出现复习任务。</p>')}</div>`}
function deferReview(id){const r=state.reviews.find(x=>x.course===id);openModal('调整复习日期',`<p>${esc(courses[id].title)}：${r.date} → ${shiftDate(r.date,1)}</p><p class="sub">本次延期保留在记录中。</p>${btn('确认延期',`confirmDefer('${id}')`,'primary space')}`)}
function confirmDefer(id){const r=state.reviews.find(x=>x.course===id);r.history.push({type:'延期',at:Date.now(),from:r.date,to:shiftDate(r.date,1)});r.date=shiftDate(r.date,1);save();closeModal();render()}
function startReview(id){rememberDraft();pauseActive();state.reviewRun={course:id,hinted:false,answer:null,correct:null,confirmed:false};state.page='review-run';save();render('top')}
function reviewRunPage(){const r=state.reviewRun;if(!r)return reviewPage();const c=courses[r.course];return `<div class="section">${head(c.title+' · 独立回忆','先回答，再给反馈；本次题目只作复习检查。')}${messages()}${r.answer===null?question(c.review,'复习题'):panel('这次复习的证据',`<div class="notice ${r.correct&&!r.hinted?'green':'amber'}">${r.correct&&!r.hinted?'独立回答正确':r.hinted?'使用过提示，仅作训练':'还需要补学'}</div><p class="space">${esc(c.review.reason)}</p><p class="sub">下一次建议：${dateAt(r.correct&&!r.hinted?7:1)}。本轮不自动提高正式掌握度。</p><div class="actions space">${btn('确认复习记录','confirmReview()','primary')}${btn('回到课程补学',`startCourse('${c.id}')`)}</div>`)}</div>`}
function confirmReview(){const run=state.reviewRun;if(!run||run.answer===null)return;const r=state.reviews.find(x=>x.course===run.course);r.history.push({type:'回忆',at:Date.now(),answer:run.answer,correct:run.correct,hinted:run.hinted});r.needsHelp=!(run.correct&&!run.hinted);r.date=dateAt(r.needsHelp?1:7);state.reviewRun=null;state.page='review';save();render('top');toast('复习结果与日期已确认')}
function statsPage(){const list=Object.values(state.sessions),minutes=Math.floor(list.reduce((n,s)=>n+elapsed(s),0)/60),accepted=list.filter(s=>s.acceptance.pass).length,confirmed=list.filter(s=>s.confirmed&&complete(s)).length;return `<div class="section">${head('学习复盘','只统计当前浏览器中保留的记录，时间投入和能力证据分别看。')}<div class="grid3">${panel('实际专注',`<div class="kpi">${minutes} <span class="sub">分钟</span></div><span class="tiny">${list.length} 个已开始课程</span>`)}${panel('独立验收',`<div class="kpi">${accepted} / ${list.length}</div><span class="tiny">有提示的训练不计入通过</span>`)}${panel('课程确认通过',`<div class="kpi">${confirmed}</div><span class="tiny">验收与必交作业都满足条件</span>`)}</div>${panel('三条线的当前证据',Object.values(courses).map(c=>`<div class="chartrow"><span>${esc(c.subject)}</span><div><span>${esc(c.title)} · ${status(c.id)}</span><div class="progress"><i style="width:${state.mastery[c.id]*20}%"></i></div></div><span>${state.mastery[c.id]}/5</span></div>`).join(''))}${panel('下一轮怎样调整',`<p>${confirmed===0?'目前还没有确认通过的课程，先完成一条学习 → 作业 → 验收 → 确认流程，再扩大安排。':`已有 ${confirmed} 门课取得确认记录；优先完成余下作业，再留出复习时间。`}</p><p class="sub">计划是 ${state.plan?.tasks.reduce((n,t)=>n+t.minutes,0)||0} 分钟工作量；实际用时不足以单独判断是否学会。</p><div class="actions space">${btn('预览下一轮安排',"goto('plan')",'primary')}${btn('生成复盘草稿','weeklyDraft()')}</div>`)}</div>`}
function weeklyDraft(){const text=Object.values(courses).map(c=>`${c.subject} / ${c.title}：${status(c.id)}；正式掌握度 ${state.mastery[c.id]}/5；作业 ${ses(c.id)?.homework.versions.length||0} 个版本。`).join('\n');openModal('复盘草稿',`<textarea id="weekly-text" class="input" style="min-height:170px">${esc(text)}</textarea><p class="sub">可以补充实际感受和下一轮范围；确认后保存在本地。</p>${btn('确认保存复盘','saveWeekly()','primary space')}`)}
function saveWeekly(){const text=document.getElementById('weekly-text').value.trim();if(!text)return toast('请填写复盘内容');state.notes.push({id:'weekly-'+Date.now(),title:TODAY+' · 学习复盘',text,at:Date.now()});save();closeModal();toast('复盘已本地保存')}
function notesPage(){return `<div class="section">${head('学习笔记','确认后的记录保存在本地；可以检查和导出。')}<div class="notice">当前没有真实有道云连接。下方状态为本地已保存 / 尚未云同步，不会显示假同步成功。</div>${state.notes.length?state.notes.slice().reverse().map(n=>`<section class="card"><div class="row"><div><h3>${esc(n.title)}</h3><span class="sub">本地已保存 · 尚未云同步</span></div>${btn('导出 Markdown',`exportNote('${n.id}')`,'small')}</div><pre class="pre space">${esc(n.text)}</pre></section>`).join(''):'<div class="empty">还没有确认保存的笔记。结束一场学习后先检查总结，再确认保存。</div>'}${panel('原有资料位置',`<p class="sub">study-prep-tracker 的 daily/、weekly/、mistakes/、english/、gamedev/ 与 mastery/ 继续保留。原始资料在本原型中只读；桌面版通过 YoudaoNote CLI 查找、读取和同步。</p>`)}</div>`}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function exportNote(id){const n=state.notes.find(n=>n.id===id);if(n)download(n.title+'.md','# '+n.title+'\n\n'+n.text,'text/markdown')}
function settingsPage(){return `<div class="section">${head('设置与数据','当前是本地交互原型，连接与执行能力将在桌面版接入。')}<div class="grid2">${panel('学习偏好',`<div class="field"><label>默认讲解方式</label><select id="style" class="input"><option ${state.settings.style==='先举例，再讲原理'?'selected':''}>先举例，再讲原理</option><option ${state.settings.style==='先问再讲'?'selected':''}>先问再讲</option></select></div><div class="field"><label>每日复习预算（分钟）</label><input id="review-limit" type="number" min="5" max="60" class="input" value="${state.settings.reviewLimit}"></div>${btn('保存偏好','saveSettings()','primary space')}`)}${panel('连接状态',`<div class="item"><div class="grow">AI 模型<div class="sub">未连接 · 当前回复是课程规则演示</div></div>${badge('待实现','gray')}</div><div class="item"><div class="grow">YoudaoNote CLI<div class="sub">未连接 · 不执行实际云端写入</div></div>${badge('待实现','gray')}</div><div class="item"><div class="grow">项目运行与 Windows 提醒<div class="sub">待桌面环境接入</div></div>${badge('待实现','gray')}</div>`)}${panel('原型数据',`<p class="sub">学习状态、提交版本和输入草稿保存在当前浏览器。关闭或离开页面会暂停课程。</p><div class="actions space">${btn('导出本地数据','exportData()')}${btn('清空演示数据','resetModal()','danger')}</div>`)}</div></div>`}
function saveSettings(){state.settings.style=document.getElementById('style').value;state.settings.reviewLimit=Math.min(60,Math.max(5,Number(document.getElementById('review-limit').value)||30));save();toast('偏好已保存在本地')}
function exportData(){rememberDraft();pauseActive();save();download('知序-本地学习数据.json',JSON.stringify(state,null,2),'application/json');render()}
function resetModal(){openModal('清空本地演示数据',`<p>会删除当前浏览器中的计划、课程进展、作业版本和笔记。原始学习资料不会被改动。</p><div class="actions space">${btn('先导出数据','exportData()')}${btn('确认清空','resetData()','danger')}${btn('取消','closeModal()')}</div>`)}
function resetData(){pauseActive();state=defaults();save();closeModal();render('top')}
function openModal(title,body){rememberDraft();document.getElementById('modalroot').innerHTML=`<div class="modalback" data-action="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="row"><h2>${title}</h2><button class="close" aria-label="关闭弹窗" data-action="closeModal()">×</button></div>${body}</section></div>`;document.querySelector('.modal input,.modal textarea,.modal select,.modal button')?.focus()}
function closeModal(){document.getElementById('modalroot').innerHTML=''}
function draftInput(e){state.drafts[draftKey()]=e.value;growInput(e);save()}
function growInput(e){if(!e)return;e.style.height='42px';e.style.height=Math.min(150,Math.max(42,e.scrollHeight))+'px'}
async function attachFile(input){const file=input.files[0];if(!file)return;if(file.size>200000){input.value='';return toast('示例只读取 200KB 以内的文本材料')}try{const text=await file.text();state.drafts[draftKey()]=text;state.attachmentName=file.name;save();render();toast('材料已放入输入草稿，检查后提交')}catch{toast('读取文件失败')}input.value=''}
function sendAI(){const el=document.getElementById('aiInput'),v=el.value.trim();if(!v)return;state.drafts[draftKey()]='';el.value='';add('user',v);if(state.page==='lesson')answerCourse(v);else if(state.page==='assignment')submitHomework(v);else if(state.page==='review-run'){const r=state.reviewRun;if(r.answer!==null)add('ai','复习结果已生成，请检查并确认，或回课程补学。');else if(/提示|解释|答案/.test(v)){r.hinted=true;add('ai','获取帮助后这轮只算训练。\n'+courses[r.course].teaching)}else{r.answer=v;r.correct=grade(courses[r.course].review,v);add('ai',(r.correct?'回答符合本题标准。':'本题还需要巩固。')+'\n'+courses[r.course].review.reason)}}else generalReply(v);save();render('bottom');document.getElementById('aiInput').focus()}
function generalReply(v){if(/计划|安排|加班|分钟/.test(v)){let slots=structuredClone(state.availability);const m=v.match(/(?:今天|今晚|今日).*?(\d+)\s*(?:分钟|分)/);if(m)slots[0].minutes=Math.min(240,Math.max(0,Number(m[1])));state.planDraft=buildPlan(slots);add('ai',`已生成可检查的安排草案，共 ${state.planDraft.tasks.reduce((n,t)=>n+t.minutes,0)} 分钟，未排入 ${state.planDraft.deferred.length} 项。${m?'今天的可用容量改为 '+slots[0].minutes+' 分钟。':''}请到学习计划页检查变更并应用；正式安排目前保持原版本。`)}else if(state.page==='courses'&&state.selected){const c=courses[state.selected];add('ai',c.goal+'\n验收标准：'+c.criteria.join('；')+'。必交作业也需达标。')}else if(/进度|复盘|掌握/.test(v)){add('ai',Object.values(courses).map(c=>`${c.title}：${status(c.id)}，已确认掌握度 ${state.mastery[c.id]}/5。`).join('\n')+'\n这些结论仅依据当前本地记录；旧目录的历史值单独保留。')}else add('ai','当前原型可以完整演示三门课程的诊断、练习、作业和验收。你可以从课程页查看目标和标准，也可以告诉我“今天只有 15 分钟”预览调整后的计划。真实模型尚未连接，当前不会对任意问题伪造专业评分。')}
setInterval(()=>{const e=document.getElementById('timer');if(e)e.textContent=clock(ses(state.active))},1000);
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
document.addEventListener('visibilitychange',()=>{if(document.hidden){rememberDraft();pauseActive();save()}else render()});
window.addEventListener('beforeunload',()=>{rememberDraft();pauseActive();save()});
save();render('top');
